// The pieces the two layouts of a board share.
//
// A board can be drawn as columns of cards or as one grouped list, and the
// things that are the same either way live here rather than in one of them:
// how a date is said, what a priority is coloured, and what a heading looks
// like opened up. A row of the list opened and a card turned over are the same
// question asked twice, and answering it in two places is how they drift.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Typography from '@mui/joy/Typography';
import Tooltip from '@mui/joy/Tooltip';
import IconButton from '@mui/joy/IconButton';
import Divider from '@mui/joy/Divider';
import LinearProgress from '@mui/joy/LinearProgress';
import CircularProgress from '@mui/joy/CircularProgress';

import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import StopIcon from '@mui/icons-material/Stop';
import Inventory2Icon from '@mui/icons-material/Inventory2';
import DriveFileMoveIcon from '@mui/icons-material/DriveFileMoveOutlined';
import ContentCopyIcon from '@mui/icons-material/ContentCopyOutlined';
import ArticleIcon from '@mui/icons-material/Article';

import Checkbox from '@mui/joy/Checkbox';
import Chip from '@mui/joy/Chip';
import CheckBoxOutlinedIcon from '@mui/icons-material/CheckBoxOutlined';
import ImageOutlinedIcon from '@mui/icons-material/ImageOutlined';

import { ODb, KanbanBoard } from '../db';
import { Card } from '../kanban';
import { CheckItem, Checklist, checklistOf } from '../orgbody';
import CardVoice from './CardVoice';

// What a card's buttons can ask for.
//
// `refile` and `copy` join `archive` because the three are one operation with
// three endings, and a board is exactly where you notice that: a card in the
// wrong column is often a heading in the wrong *file*, and having to go to the
// search tab to move it is the long way round.
export type CardAction = 'archive' | 'refile' | 'copy' | 'clockin' | 'clockout';


export function baseName(path: string): string {
    const parts = path.split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

export function isSetDate(d?: { Start?: string } | null): boolean {
    return !!(d && d.Start && !d.Start.startsWith('0001-01-01'));
}

// A date said the way a person reads it on a card: today and tomorrow by name,
// this year without the year, anything else in full.
export function dateLabel(iso: string): string {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '';
    const now = new Date();
    const days = Math.round((new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
        - new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()) / 86400000);
    if (days === 0) return 'today';
    if (days === 1) return 'tomorrow';
    if (days === -1) return 'yesterday';
    if (days > 1 && days < 7) return d.toLocaleDateString(undefined, { weekday: 'short' });
    const opts: Intl.DateTimeFormatOptions = d.getFullYear() === now.getFullYear()
        ? { month: 'short', day: 'numeric' }
        : { year: 'numeric', month: 'short', day: 'numeric' };
    return d.toLocaleDateString(undefined, opts);
}

export function isOverdue(iso: string): boolean {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return false;
    const now = new Date();
    return d.getTime() < new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
}

export const PRIORITY_COLOR: Record<string, string> = { A: '#e5484d', B: '#f5a524', C: '#3e63dd' };

// ---------------------------------------------------------------------------
// What is written under a heading
// ---------------------------------------------------------------------------

export interface HeadingBody {
    text: string;
    audio: string;
    image: string;
    list: Checklist;
    loading: boolean;
}

const EMPTY_BODY: HeadingBody = {
    text: '', audio: '', image: '',
    list: { items: [], done: 0, total: 0 },
    loading: true,
};

// The body of every heading the board has asked about, kept for as long as the
// page is open.
//
// A cache module-wide rather than per card on purpose: the front of a card
// wants to know whether there is a checklist and a picture, and the back wants
// the items themselves - and a card that fetched twice for that would be two
// requests per heading on a board of forty. Keyed by hash, which changes when
// the heading does, so nothing here can go stale against the file.
const bodies = new Map<string, HeadingBody>();
const inFlight = new Map<string, Promise<HeadingBody>>();
const listeners = new Set<() => void>();

function announce() { listeners.forEach(l => l()); }

// Read one back from the server, keeping what is on screen until the new one
// arrives.
//
// Dropping the old body first would be simpler and is wrong: the card would
// have nothing to draw for as long as the request takes, so ticking a box
// makes the whole checklist blink out and come back. What is there is stale
// for a moment; blank is worse than stale.
export function refreshBody(hash: string) {
    inFlight.delete(hash);
    fetchBody(hash);
}

// Every body the board is holding, for when it reads itself back. A heading's
// hash does not change when its text does, so nothing here expires on its own
// - and a card still showing the checklist from before somebody edited the
// file in another window is exactly the kind of wrong that looks right.
export function forgetAllBodies() {
    const known = Array.from(bodies.keys());
    inFlight.clear();
    known.forEach(h => fetchBody(h));
}

function fetchBody(hash: string): Promise<HeadingBody> {
    const going = inFlight.get(hash);
    if (going) return going;
    const p = ODb.todoBody(hash)
        .then(r => {
            const text = (r && r.Text) || '';
            const body: HeadingBody = {
                text,
                audio: (r && r.Audio) || '',
                image: (r && r.Image) || '',
                list: checklistOf(text),
                loading: false,
            };
            bodies.set(hash, body);
            inFlight.delete(hash);
            announce();
            return body;
        })
        .catch(() => {
            const body = { ...EMPTY_BODY, loading: false };
            bodies.set(hash, body);
            inFlight.delete(hash);
            announce();
            return body;
        });
    inFlight.set(hash, p);
    return p;
}

// What a heading says, fetched if nobody has asked yet.
export function useHeadingBody(hash: string): HeadingBody {
    const [, bump] = React.useReducer((n: number) => n + 1, 0);

    React.useEffect(() => {
        listeners.add(bump);
        return () => { listeners.delete(bump); };
    }, []);

    React.useEffect(() => {
        if (hash !== '' && !bodies.has(hash)) fetchBody(hash);
    }, [hash]);

    return bodies.get(hash) || EMPTY_BODY;
}

// ---------------------------------------------------------------------------
// The checklist
// ---------------------------------------------------------------------------

// The badge on the front of a card: the Trello mark, and how many of the boxes
// are ticked. It goes green when they all are, which is the one state worth
// seeing without reading the numbers.
export function ChecklistBadge({ list }: { list: Checklist }) {
    if (list.total === 0) return null;
    const all = list.done === list.total;
    return (
        <Tooltip size="sm" title={`${list.done} of ${list.total} ticked — turn the card over to change them`}>
            <Chip
                size="sm"
                variant={all ? 'soft' : 'outlined'}
                color={all ? 'success' : 'neutral'}
                startDecorator={<CheckBoxOutlinedIcon sx={{ fontSize: 12 }} />}
                sx={{ '--Chip-minHeight': '18px', fontSize: 10, fontVariantNumeric: 'tabular-nums' }}
            >
                {list.done}/{list.total}
            </Chip>
        </Tooltip>
    );
}

// The list itself, on the back of the card.
//
// Ticking a box writes that one line of the org file and nothing else. The box
// moves at once and is put back if the server refuses - which it will if the
// item has changed underneath, because the write names the text it expects as
// well as the position.
export function ChecklistPanel({ card, list }: {
    card: Card;
    list: Checklist;
}) {
    const [busy, setBusy] = React.useState<Record<number, boolean>>({});
    const [local, setLocal] = React.useState<Record<number, boolean>>({});
    const [failed, setFailed] = React.useState('');

    // A fresh body from the server is the truth again.
    React.useEffect(() => { setLocal({}); }, [list]);

    if (list.total === 0) return null;

    const stateOf = (i: CheckItem) => (local[i.index] === undefined ? i.done : local[i.index]);
    const done = list.items.filter(stateOf).length;

    const toggle = async (item: CheckItem) => {
        const want = !stateOf(item);
        setLocal(l => ({ ...l, [item.index]: want }));
        setBusy(b => ({ ...b, [item.index]: true }));
        setFailed('');
        try {
            const res: any = await ODb.setChecklistItem(card.Hash, item.index, item.text, want);
            if (!res || res.Ok === false) {
                setLocal(l => ({ ...l, [item.index]: !want }));
                setFailed((res && res.Msg) || 'That did not go through.');
            } else {
                // Read it back rather than trusting the optimistic tick: the
                // file is the only place this state really lives. Only this
                // heading - nothing the board itself shows has changed, and a
                // whole refresh to tick a box would redraw every card.
                refreshBody(card.Hash);
            }
        } catch {
            setLocal(l => ({ ...l, [item.index]: !want }));
            setFailed('The server did not take that.');
        }
        setBusy(b => ({ ...b, [item.index]: false }));
    };

    return (
        <Box sx={{ mb: 1 }} onClick={e => e.stopPropagation()}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75, mb: 0.5 }}>
                <CheckBoxOutlinedIcon sx={{ fontSize: 13, color: 'text.tertiary' }} />
                <Typography level="body-xs" sx={{ color: 'text.tertiary', fontVariantNumeric: 'tabular-nums' }}>
                    {done}/{list.total}
                </Typography>
                <LinearProgress
                    determinate
                    value={list.total === 0 ? 0 : (done / list.total) * 100}
                    color={done === list.total ? 'success' : 'primary'}
                    sx={{ flex: 1, '--LinearProgress-thickness': '4px' }}
                />
            </Box>
            {list.items.map(item => (
                <Box
                    key={item.index}
                    sx={{ display: 'flex', alignItems: 'flex-start', gap: 0.75, pl: item.depth * 1.5, py: '1px' }}
                >
                    <Checkbox
                        size="sm"
                        checked={stateOf(item)}
                        disabled={busy[item.index]}
                        onChange={() => toggle(item)}
                        sx={{ '--Checkbox-size': '14px', mt: '1px' }}
                    />
                    <Typography
                        level="body-xs"
                        sx={{
                            fontSize: 11.5, lineHeight: 1.45, minWidth: 0,
                            textDecoration: stateOf(item) ? 'line-through' : 'none',
                            color: stateOf(item) ? 'text.tertiary' : 'text.secondary',
                            cursor: 'pointer',
                        }}
                        onClick={() => { if (!busy[item.index]) toggle(item); }}
                    >
                        {item.text}
                    </Typography>
                </Box>
            ))}
            {failed !== '' && (
                <Typography level="body-xs" sx={{ color: 'danger.softColor', mt: 0.5 }}>
                    {failed}
                </Typography>
            )}
        </Box>
    );
}

// ---------------------------------------------------------------------------
// Pasting a picture onto a card
// ---------------------------------------------------------------------------
//
// A paste has no target of its own: the event lands on the document, not on
// whatever the eye happens to be on. So the backs that are open keep a stack
// here and the last one to be turned over takes the paste - which is the one
// somebody is looking at, because turning a card over is what put it there.
//
// The picture goes into the org directory and a link is appended to the
// heading, which is what makes it turn up on the front of the card: the front
// already draws the first picture the heading points at, and this is now one.

const pasteStack: string[] = [];

function usePasteTarget(hash: string, onPaste: (file: Blob, type: string, name: string) => void) {
    const cb = React.useRef(onPaste);
    cb.current = onPaste;

    React.useEffect(() => {
        if (hash === '') return;
        pasteStack.push(hash);
        return () => {
            const at = pasteStack.lastIndexOf(hash);
            if (at >= 0) pasteStack.splice(at, 1);
        };
    }, [hash]);

    React.useEffect(() => {
        if (hash === '') return;
        const onDocPaste = (ev: ClipboardEvent) => {
            // The last card turned over is the one being looked at.
            if (pasteStack[pasteStack.length - 1] !== hash) return;
            // Anything typed into is somebody pasting text where text goes.
            const el = document.activeElement as HTMLElement | null;
            if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable)) return;

            const items = ev.clipboardData ? Array.from(ev.clipboardData.items) : [];
            const shot = items.find(i => i.kind === 'file' && i.type.indexOf('image/') === 0);
            if (!shot) return;
            const file = shot.getAsFile();
            if (!file) return;
            ev.preventDefault();
            cb.current(file, file.type || shot.type, file.name || 'paste');
        };
        document.addEventListener('paste', onDocPaste);
        return () => document.removeEventListener('paste', onDocPaste);
    }, [hash]);
}

// The line on the back of a card that says a picture can go here, and says
// what happened when one did.
export function CardPaste({ card }: { card: Card }) {
    const [state, setState] = React.useState<'idle' | 'saving' | 'done' | 'failed'>('idle');
    const [msg, setMsg] = React.useState('');

    usePasteTarget(card.Hash, async (blob, type, name) => {
        setState('saving');
        setMsg('Keeping the picture…');
        try {
            const res = await ODb.pasteImage(card.Hash, blob, type, name);
            if (!res || res.Ok === false) {
                setState('failed');
                setMsg((res && res.Msg) || 'That paste did not go through.');
                return;
            }
            // The front of the card draws the first picture the heading points
            // at, so reading the body back is all it takes to show it.
            refreshBody(card.Hash);
            setState('done');
            setMsg('Added to this heading.');
            window.setTimeout(() => { setState('idle'); setMsg(''); }, 2500);
        } catch (e: any) {
            setState('failed');
            setMsg((e && e.message) || 'That paste did not go through.');
        }
    });

    return (
        <Box
            sx={{
                display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0,
                color: state === 'failed' ? 'danger.softColor' : 'text.tertiary',
            }}
        >
            {state === 'saving'
                ? <CircularProgress size="sm" sx={{ '--CircularProgress-size': '12px' }} />
                : <ImageOutlinedIcon sx={{ fontSize: 12 }} />}
            <Typography level="body-xs" sx={{ fontSize: 10, color: 'inherit', minWidth: 0 }} noWrap title={msg}>
                {msg !== '' ? msg : 'Paste a picture to add it here'}
            </Typography>
        </Box>
    );
}

// ---------------------------------------------------------------------------
// The recording and the picture
// ---------------------------------------------------------------------------

// The player on the back of a card. Nothing is fetched until it is asked for,
// the same as the one the html export puts on a heading.
export function CardAudio({ src }: { src: string }) {
    if (src === '') return null;
    return (
        <Box sx={{ mb: 1 }} onClick={e => e.stopPropagation()}>
            <audio
                src={src}
                controls
                preload="none"
                style={{ width: '100%', height: 30, colorScheme: 'light dark' }}
            />
        </Box>
    );
}

// The picture on the front. Scaled to the card's width and cropped to a band
// rather than shown whole: a card is a summary, and a portrait photograph
// given its own way would be the whole card.
export function CardImage({ src, alt }: { src: string; alt: string }) {
    const [ok, setOk] = React.useState(true);
    if (src === '' || !ok) return null;
    return (
        <Box sx={{
            mb: 0.75,
            borderRadius: 'md',
            overflow: 'hidden',
            background: 'var(--joy-palette-background-level2)',
            // A hairline inside the frame rather than a border outside it:
            // the picture keeps its full width and the edge reads as part of
            // the card rather than as a box drawn round something.
            boxShadow: 'inset 0 0 0 1px var(--joy-palette-divider)',
            position: 'relative',
            // Nothing is known about what was pasted, and a photograph that
            // ends in white sits on a white card with no edge at all. A soft
            // wash at the foot gives it one without tinting the picture.
            '&::after': {
                content: '""',
                position: 'absolute', left: 0, right: 0, bottom: 0, height: '38%',
                background: 'linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.16) 100%)',
                pointerEvents: 'none',
            },
        }}>
            <Box
                component="img"
                src={src}
                alt={alt}
                loading="lazy"
                onError={() => setOk(false)}
                sx={{ display: 'block', width: '100%', height: 96, objectFit: 'cover' }}
            />
        </Box>
    );
}

// What a heading says, under its own name: the text written under it and the
// properties on it, and the two things you can do to it from here. Shared by
// the back of a card and by a row of the list opened up, which are the same
// question asked in two layouts.
export function CardDetail({ card, board, clocked, onAct }: {
    card: Card; board: KanbanBoard; clocked: boolean;
    onAct: (what: CardAction, card: Card) => void;
}) {
    const [html, setHtml] = React.useState<string | null>(null);
    const [loading, setLoading] = React.useState(false);
    const wants = board.backShows === 'body' || board.backShows === 'both';

    // One fetch, when the back is first mounted - which the card only does once
    // it has been turned over, so a column of forty cards is not forty requests
    // for text nobody asked to read. Note what is *not* in the dependency list:
    // loading and html both change while this is running, and either of them in
    // there would tear the effect down and cancel the fetch it just started.
    React.useEffect(() => {
        if (!wants) return;
        let alive = true;
        setLoading(true);
        ODb.todoHtml(card.Hash).then(r => {
            if (!alive) return;
            setHtml((r && r.Content) || '');
            setLoading(false);
        }).catch(() => { if (alive) { setHtml(''); setLoading(false); } });
        return () => { alive = false; };
    }, [card.Hash, wants]);

    const props = card.Props || {};
    const propNames = Object.keys(props).filter(k => props[k] !== '');
    const showProps = board.backShows === 'properties' || board.backShows === 'both';

    // The recording and the checklist come from the heading's own text rather
    // than from the rendered html above, and both go before it: a list you can
    // tick and a thing you can play are what the back of the card is for.
    const body = useHeadingBody(card.Hash);

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, minWidth: 0 }}>
            <Box sx={{ flex: 1, overflowY: 'auto', minHeight: 0, pr: 0.5 }}>
                <CardAudio src={body.audio} />
                <ChecklistPanel card={card} list={body.list} />
                {wants && (
                    loading ? <LinearProgress size="sm" sx={{ my: 1 }} /> : (
                        html === '' || html === null ? (
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                                Nothing written under this heading.
                            </Typography>
                        ) : (
                            <Box
                                sx={{
                                    fontSize: 11.5, lineHeight: 1.45, color: 'text.secondary',
                                    '& p': { m: 0, mb: 0.5 },
                                    '& ul, & ol': { m: 0, pl: 2 },
                                    '& img': { maxWidth: '100%' },
                                    '& pre': { fontSize: 10, overflowX: 'auto', p: 0.5, borderRadius: 4, background: 'var(--joy-palette-background-level2)' },
                                    '& table': { fontSize: 10, borderCollapse: 'collapse' },
                                    '& td, & th': { border: '1px solid var(--joy-palette-divider)', px: 0.5 },
                                    '& h1, & h2, & h3, & h4': { fontSize: 12, m: 0, mt: 0.5, mb: 0.25 },
                                }}
                                dangerouslySetInnerHTML={{ __html: html }}
                            />
                        )
                    )
                )}
                {showProps && propNames.length > 0 && (
                    <Box sx={{ mt: wants ? 1 : 0 }}>
                        {propNames.map(k => (
                            <Box key={k} sx={{ display: 'flex', gap: 1, fontSize: 10.5, lineHeight: 1.6, minWidth: 0 }}>
                                <Typography level="body-xs" sx={{ fontFamily: 'monospace', fontSize: 10, color: 'text.tertiary', flexShrink: 0 }}>
                                    {k}
                                </Typography>
                                <Typography level="body-xs" sx={{ fontSize: 10.5, minWidth: 0 }} noWrap title={props[k]}>
                                    {props[k]}
                                </Typography>
                            </Box>
                        ))}
                    </Box>
                )}
                {showProps && propNames.length === 0 && !wants && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                        No properties on this heading.
                    </Typography>
                )}
            </Box>
            <CardPaste card={card} />
            <Divider sx={{ my: 0.75 }} />
            {/* Every one of these says what it *does*, not what it is called.
                They are three small glyphs at the bottom of a card and there is
                nothing else on screen to work them out from - "Archive" and
                "Archive this heading out of the file, where it stops matching
                the query" are not the same amount of help before pressing
                something that moves text out of a file. Placed above, because
                below is where the pointer already is. */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0 }}>
                <Tooltip
                    size="sm"
                    placement="top-start"
                    enterDelay={300}
                    title={`This heading is line ${card.LineNum} of ${card.Filename}`}
                >
                    <Typography level="body-xs" sx={{ fontSize: 10, color: 'text.tertiary', minWidth: 0 }} noWrap>
                        <ArticleIcon sx={{ fontSize: 11, mr: 0.25, verticalAlign: '-1px' }} />
                        {baseName(card.Filename)}:{card.LineNum}
                    </Typography>
                </Tooltip>
                {/* Speaking into the heading. Beside the clock and the
                    archive, because it is the third thing you can do to a
                    heading from here. */}
                <CardVoice card={card} onDone={() => { /* the body reads itself back */ }} />
                <Box sx={{ ml: 'auto', display: 'flex', gap: 0.25 }} onClick={e => e.stopPropagation()}>
                    <Tooltip
                        size="sm"
                        placement="top"
                        enterDelay={300}
                        title={clocked
                            ? 'Stop the clock. The time since you started is written into this heading’s LOGBOOK.'
                            : 'Start the clock on this heading. Org records the time against it, and the Clock Report adds it up.'}
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color={clocked ? 'danger' : 'neutral'}
                            aria-label={clocked ? 'Stop the clock on this heading' : 'Start the clock on this heading'}
                            onClick={() => onAct(clocked ? 'clockout' : 'clockin', card)}
                        >
                            {clocked ? <StopIcon sx={{ fontSize: 14 }} /> : <PlayArrowIcon sx={{ fontSize: 14 }} />}
                        </IconButton>
                    </Tooltip>
                    <Tooltip
                        size="sm"
                        placement="top-end"
                        enterDelay={300}
                        title="Refile this heading somewhere else. A card in the wrong column is often a heading in the wrong file."
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color="neutral"
                            aria-label="Refile this heading"
                            onClick={() => onAct('refile', card)}
                        >
                            <DriveFileMoveIcon sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                    <Tooltip
                        size="sm"
                        placement="top-end"
                        enterDelay={300}
                        title="Copy this heading somewhere else, leaving it here as well."
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color="neutral"
                            aria-label="Copy this heading"
                            onClick={() => onAct('copy', card)}
                        >
                            <ContentCopyIcon sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                    <Tooltip
                        size="sm"
                        placement="top-end"
                        enterDelay={300}
                        title="Archive this heading. It is moved out of the file into its archive, so it stops matching the query and leaves the board."
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color="neutral"
                            aria-label="Archive this heading"
                            onClick={() => onAct('archive', card)}
                        >
                            <Inventory2Icon sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                </Box>
            </Box>
        </Box>
    );
}


