// An org table, drawn the way the Tables tab draws one.
//
// Read-only on purpose. The Tables tab reads a table from the server with its
// formulas, its column names and its cell references, and edits it through
// endpoints that know all of that; this is for *showing* a table where it was
// written - in the search tab's inspect view - and a grid that looked editable
// but was not would be worse than one that plainly is not.
//
// What it borrows from the Tables tab is everything about how one looks: the
// same gloss on the rulers, the same hairline divider between cells, the same
// monospace measure, and a rule drawn as the Tables tab draws one - a band with
// a hairline fading out at both ends rather than a row of dashes. The three
// constants below are copied from `Spreadsheet.tsx` deliberately: they are what
// makes the two grids read as the same object, so a change to one is a change
// to make here as well.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Chip from '@mui/joy/Chip';
import Typography from '@mui/joy/Typography';
import Tooltip from '@mui/joy/Tooltip';
import FunctionsIcon from '@mui/icons-material/Functions';

import { OrgTable } from '../orgbody';

// The Tables tab's gloss: a light top and a dark bottom, both almost nothing,
// which is what keeps a ruler looking raised without looking painted.
const GLOSS = 'linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0) 52%, rgba(0,0,0,0.035))';

const CELL_MIN_WIDTH = 96;

const RULER: React.CSSProperties = {
    borderRight: '1px solid var(--joy-palette-divider)',
    borderBottom: '1px solid var(--joy-palette-divider)',
    backgroundColor: 'var(--joy-palette-background-level1)',
    backgroundImage: GLOSS,
    color: 'var(--joy-palette-text-tertiary)',
    fontFamily: 'var(--joy-fontFamily-code, monospace)',
    fontSize: '11px',
    fontWeight: 600,
    letterSpacing: '0.03em',
    textAlign: 'center',
    padding: '3px 4px',
    position: 'sticky',
    userSelect: 'none',
    minWidth: 46,
};

const CELL: React.CSSProperties = {
    borderRight: '1px solid var(--joy-palette-divider)',
    borderBottom: '1px solid var(--joy-palette-divider)',
    fontFamily: 'var(--joy-fontFamily-code, monospace)',
    fontSize: '12.5px',
    padding: '4px 8px',
    whiteSpace: 'pre',
    minWidth: CELL_MIN_WIDTH,
    color: 'var(--joy-palette-text-secondary)',
};

// A number reads right, a word reads left. The one thing that makes a column of
// readings scannable, and the Tables tab does the same.
const NUMERIC = /^[-+]?[\d.,]+%?$/;

export default function OrgTableView({ table }: { table: OrgTable }) {
    // The first row is a header when the table rules straight after it, which
    // is how an org table says so.
    const headerAt = table.rows.length > 1 && table.rows[1].rule ? 0 : -1;

    // A rule is drawn as a band of its own rather than folded into the row
    // above, because that is how the Tables tab draws one and because a table
    // that rules twice in a row would otherwise lose one of them.
    const lines: { kind: 'row' | 'rule'; cells: string[]; n: number }[] = [];
    let n = 0;
    for (const row of table.rows) {
        if (row.rule) {
            lines.push({ kind: 'rule', cells: [], n: 0 });
            continue;
        }
        n += 1;
        lines.push({ kind: 'row', cells: row.cells, n });
    }

    const cols = Array.from({ length: table.cols }, (_, i) => i);

    return (
        <Box sx={{ my: 1.5 }}>
            {(table.name !== '' || table.formulas.length > 0) && (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75, mb: 0.625, flexWrap: 'wrap' }}>
                    {table.name !== '' && (
                        <Chip
                            size="sm"
                            variant="soft"
                            color="primary"
                            sx={{ fontFamily: 'var(--joy-fontFamily-code, monospace)', fontSize: 11 }}
                        >
                            {table.name}
                        </Chip>
                    )}
                    {table.formulas.map((f, i) => (
                        <Tooltip key={i} size="sm" title="A formula the table computes itself" variant="outlined">
                            <Chip
                                size="sm"
                                variant="outlined"
                                color="neutral"
                                startDecorator={<FunctionsIcon sx={{ fontSize: 13 }} />}
                                sx={{
                                    fontFamily: 'var(--joy-fontFamily-code, monospace)',
                                    fontSize: 10.5,
                                    color: 'text.tertiary',
                                }}
                            >
                                {f}
                            </Chip>
                        </Tooltip>
                    ))}
                </Box>
            )}

            <Sheet
                variant="outlined"
                sx={{
                    borderRadius: 'md',
                    boxShadow: 'xs',
                    overflow: 'auto',
                    maxHeight: 420,
                    // The grid is its own width; the sheet is the window onto
                    // it, which is what lets a wide table scroll rather than
                    // squeeze its columns.
                    '& table': { borderCollapse: 'collapse' },
                }}
            >
                <Box sx={{ display: 'inline-block', minWidth: '100%' }}>
                    <table>
                        <thead>
                            <tr>
                                <th style={{ ...RULER, top: 0, left: 0, zIndex: 3 }} />
                                {cols.map(c => (
                                    <th key={c} style={{ ...RULER, top: 0, zIndex: 2, minWidth: CELL_MIN_WIDTH }}>
                                        ${c + 1}
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {lines.map((line, i) => line.kind === 'rule' ? (
                                <tr key={`r${i}`}>
                                    <td
                                        colSpan={table.cols + 1}
                                        style={{
                                            padding: 0,
                                            height: 9,
                                            backgroundColor: 'var(--joy-palette-background-level1)',
                                            backgroundImage: GLOSS,
                                            borderBottom: '1px solid var(--joy-palette-divider)',
                                        }}
                                    >
                                        <Box sx={{
                                            height: '1px',
                                            mx: 0.75,
                                            background: 'linear-gradient(90deg, transparent, var(--joy-palette-neutral-outlinedBorder) 8%, var(--joy-palette-neutral-outlinedBorder) 92%, transparent)',
                                        }} />
                                    </td>
                                </tr>
                            ) : (
                                <Box
                                    component="tr"
                                    key={`n${line.n}`}
                                    sx={{ '&:hover td': { backgroundColor: 'var(--joy-palette-background-level1)' } }}
                                >
                                    <td style={{ ...RULER, left: 0, zIndex: 1 }}>@{line.n}</td>
                                    {cols.map(c => {
                                        const text = line.cells[c] || '';
                                        const head = line.n - 1 === headerAt;
                                        return (
                                            <td
                                                key={c}
                                                style={{
                                                    ...CELL,
                                                    textAlign: NUMERIC.test(text.trim()) ? 'right' : 'left',
                                                    ...(head ? {
                                                        fontWeight: 700,
                                                        color: 'var(--joy-palette-text-primary)',
                                                        backgroundColor: 'var(--joy-palette-background-level1)',
                                                        backgroundImage: GLOSS,
                                                    } : {}),
                                                }}
                                            >
                                                {text}
                                            </td>
                                        );
                                    })}
                                </Box>
                            ))}
                        </tbody>
                    </table>
                </Box>
            </Sheet>

            <Typography level="body-xs" sx={{ color: 'text.tertiary', fontSize: 10, mt: 0.375 }}>
                Read only — open it in the Tables tab to edit
            </Typography>
        </Box>
    );
}
