// A QR code for reaching this server from a phone.
//
// The reason it is not simply a code of `window.location.href`: the address in
// the bar is almost always `localhost`, and a phone pointed at `localhost`
// reaches itself. Only the machine running the server knows what it is called
// on the network, so it is asked (`/addresses`), and every address it has is
// offered rather than guessed between - a laptop on wifi with a dock has
// several, and which one a phone can reach depends on the network it is on.
//
// The page's own address is offered too, at the bottom: on a server actually
// reached by name it is the right answer, and on localhost it is at least
// honest about being useless.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Tooltip from '@mui/joy/Tooltip';
import ListItem from '@mui/joy/ListItem';
import ListItemButton from '@mui/joy/ListItemButton';
import CircularProgress from '@mui/joy/CircularProgress';
import Chip from '@mui/joy/Chip';
import { useColorScheme } from '@mui/joy/styles';

import QrCode2Icon from '@mui/icons-material/QrCode2';

import * as Db from '../db';

// The encoder is a chunk of Reed-Solomon that nobody wants in the first load.
let qrMod: any = null;
function loadQr(): Promise<any> {
    if (qrMod) return Promise.resolve(qrMod);
    return import('qrcode').then(m => { qrMod = m; return m; });
}

interface Addresses {
    Ok: boolean;
    Urls: string[];
    Port: number;
    TlsPort: number;
    Msg: string;
}

export default function QrCode() {
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';

    const [open, setOpen] = React.useState(false);
    const [addrs, setAddrs] = React.useState<Addresses | null>(null);
    const [chosen, setChosen] = React.useState('');
    const [png, setPng] = React.useState('');
    const [copied, setCopied] = React.useState(false);

    const here = typeof window === 'undefined' ? '' : window.location.origin;

    React.useEffect(() => {
        if (!open) return;
        let alive = true;
        Db.ODb.serverAddresses()
            .then(r => {
                if (!alive) return;
                const got: Addresses = r || { Ok: false, Urls: [], Port: 0, TlsPort: 0, Msg: '' };
                setAddrs(got);
                setChosen(c => (c !== '' ? c : (got.Urls && got.Urls.length > 0 ? got.Urls[0] : here)));
            })
            .catch(() => {
                if (!alive) return;
                setAddrs({ Ok: false, Urls: [], Port: 0, TlsPort: 0, Msg: 'Could not ask the server what it is called.' });
                setChosen(c => (c !== '' ? c : here));
            });
        return () => { alive = false; };
    }, [open, here]);

    React.useEffect(() => {
        if (!open || chosen === '') return;
        let alive = true;
        loadQr().then(qr => {
            if (!alive) return;
            // Drawn dark-on-light whatever the app's theme: a phone camera
            // reads a light code far less reliably, and this is the one thing
            // on the page that is not being looked at by a person.
            qr.toDataURL(chosen, {
                errorCorrectionLevel: 'M',
                margin: 2,
                width: 320,
                color: { dark: '#000000ff', light: '#ffffffff' },
            }).then((url: string) => { if (alive) setPng(url); })
                .catch(() => { if (alive) setPng(''); });
        });
        return () => { alive = false; };
    }, [open, chosen]);

    const copy = () => {
        if (chosen === '' || !navigator.clipboard) return;
        navigator.clipboard.writeText(chosen).then(() => {
            setCopied(true);
            window.setTimeout(() => setCopied(false), 1400);
        }).catch(() => { /* a browser that will not copy is not worth a message */ });
    };

    const urls = addrs && addrs.Urls ? addrs.Urls : [];
    const localOnly = here.indexOf('//localhost') >= 0 || here.indexOf('//127.0.0.1') >= 0;

    return (
        <React.Fragment>
            <ListItem>
                <Tooltip size="sm" title="Open this on a phone" placement="right">
                    <ListItemButton onClick={() => setOpen(true)}>
                        <QrCode2Icon />
                    </ListItemButton>
                </Tooltip>
            </ListItem>

            <Modal open={open} onClose={() => setOpen(false)}>
                <ModalDialog variant="outlined" sx={{ width: 'min(400px, 94vw)', p: 2, gap: 1.25 }}>
                    <ModalClose />
                    <Box>
                        <Typography level="title-md">Open this on a phone</Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            Point a camera at the code. The phone has to be on the same network.
                        </Typography>
                    </Box>

                    <Box sx={{
                        display: 'flex', justifyContent: 'center', alignItems: 'center',
                        minHeight: 240, borderRadius: 'md', overflow: 'hidden',
                        background: '#ffffff', p: 1,
                    }}>
                        {png !== '' ? (
                            <Box component="img" src={png} alt={chosen} sx={{ width: 220, height: 220, display: 'block' }} />
                        ) : (
                            <CircularProgress size="sm" />
                        )}
                    </Box>

                    <Tooltip size="sm" title={copied ? 'Copied' : 'Copy this address'}>
                        <Sheet
                            variant="soft"
                            onClick={copy}
                            sx={{
                                borderRadius: 'sm', px: 1.25, py: 0.75, cursor: 'pointer',
                                fontFamily: 'monospace', fontSize: 12, textAlign: 'center',
                                wordBreak: 'break-all',
                            }}
                        >
                            {chosen || '…'}
                        </Sheet>
                    </Tooltip>

                    {addrs === null ? (
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            Asking the server what it is called…
                        </Typography>
                    ) : urls.length > 1 ? (
                        <Box>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.5 }}>
                                This machine has more than one address. Try another if the first will not open.
                            </Typography>
                            <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                                {urls.map(u => (
                                    <Chip
                                        key={u}
                                        size="sm"
                                        variant={u === chosen ? 'solid' : 'outlined'}
                                        color="neutral"
                                        onClick={() => setChosen(u)}
                                        sx={{ fontFamily: 'monospace', fontSize: 11 }}
                                    >
                                        {u.replace(/^https?:\/\//, '')}
                                    </Chip>
                                ))}
                                {here !== '' && urls.indexOf(here) < 0 && (
                                    <Chip
                                        size="sm"
                                        variant={here === chosen ? 'solid' : 'outlined'}
                                        color="neutral"
                                        onClick={() => setChosen(here)}
                                        sx={{ fontFamily: 'monospace', fontSize: 11 }}
                                    >
                                        {here.replace(/^https?:\/\//, '')}
                                    </Chip>
                                )}
                            </Box>
                        </Box>
                    ) : urls.length === 0 ? (
                        <Typography level="body-xs" sx={{ color: 'warning.softColor' }}>
                            {localOnly
                                ? 'This machine has no address on a network other than its own, so a phone has nowhere to go.'
                                : (addrs.Msg || 'The server did not say what else it is called.')}
                        </Typography>
                    ) : null}

                    {dark && (
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            The code is drawn on white on purpose — cameras read it far better that way.
                        </Typography>
                    )}
                </ModalDialog>
            </Modal>
        </React.Fragment>
    );
}
